import{_ as r,a0 as p,w as n,s,ao as i,I as u,a1 as e,A as l,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"新面孔、新功能的 Tomahawk 音乐播放器 | LCTT x X-CMD","titleTemplate":false,"description":"新面孔、新功能的 Tomahawk 音乐播放器 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"新面孔、新功能的 Tomahawk 音乐播放器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"新面孔、新功能的 Tomahawk 音乐播放器 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141106 Tomahawk Music Player Returns With New Look, Features","title":"新面孔、新功能的 Tomahawk 音乐播放器","tag":"201503","desc":""},"relativePath":"201503/20141106 Tomahawk Music Player Returns With New Look, Features.md","filePath":"[post].md"}'),m={name:"201503/20141106 Tomahawk Music Player Returns With New Look, Features.md"};function h(w,a,k,d,T,f){const o=p("Link");return n(),s("div",null,[a[14]||(a[14]=i(`<h1 id="新面孔、新功能的-tomahawk-音乐播放器" tabindex="-1">新面孔、新功能的 Tomahawk 音乐播放器 <a class="header-anchor" href="#新面孔、新功能的-tomahawk-音乐播放器" aria-label="Permalink to “新面孔、新功能的 Tomahawk 音乐播放器”">​</a></h1><p>**在悄无声息得过了一年之后，Tomahawk——音乐播放器中的瑞士军刀——带着值得歌颂的全新发行版回归了。 **</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/tomahawk-tile-1.jpg" alt=""></p><p>这个0.8版的开源跨平台应用增添了<strong>更多在线服务的支持</strong>，更新了它的外观，又一次确保了它创新的社交功能完美运行。</p><h3 id="tomahawk——两个世界的极品" tabindex="-1">Tomahawk——两个世界的极品 <a class="header-anchor" href="#tomahawk——两个世界的极品" aria-label="Permalink to “Tomahawk——两个世界的极品”">​</a></h3><p>Tomahawk 将一个传统的应用结构与我们的“即时”现代文化相结合。它可以浏览和播放本地的音乐和Spotify、Grooveshark以及SoundCloud这类的线上音乐。在最新的发行版中，它把Google Play Music和Beats Music列入了它的名册。</p><p>这可能听着很繁复或令人困惑，但实际上它表现得出奇的好。</p><p>若你想要播放一首歌，而且不介意它是从哪里来的，你只需告诉Tomahawk这个音乐的标题和作者，它就会自动从可获取的源里找出高品质版本的音乐——你不需要做任何事。</p><p><img src="http://i.imgur.com/nk5oixy.jpg" alt=""></p><p>这个应用还弄了一些附加的功能，比如EchoNest剖析，Last.fm建议，还有对Jabber的支持，这样你就能“播放”朋友的音乐。它还有一个内置的信息服务，以便于你能和其他人快速的分享播放列表和音乐。</p><blockquote><p>“这种从根本上就与众不同的听音乐的方式，开启了前所未有的音乐的消费和分享体验”，该项目的网站上这样写道。而且即便它如此独特，这也没有错。</p></blockquote><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/tomahawk-controllers.jpg" alt="Tomahawk supports the Sound Menu"></p><p><em>支持声音菜单</em></p><h3 id="tomahawk0-8发行版的亮点" tabindex="-1">Tomahawk0.8发行版的亮点 <a class="header-anchor" href="#tomahawk0-8发行版的亮点" aria-label="Permalink to “Tomahawk0.8发行版的亮点”">​</a></h3><ul><li>新的交互界面</li><li>对Beats Music的支持</li><li>对Google Play Music的支持（保存的和播放全部链接）</li><li>支持拖拽iTunes，Spotify这类网站的链接</li><li>正在播放的提示</li><li>Android应用（测试版）</li><li>收件箱的改进</li></ul><h3 id="在ubuntu上安装tomahawk0-8" tabindex="-1">在Ubuntu上安装Tomahawk0.8 <a class="header-anchor" href="#在ubuntu上安装tomahawk0-8" aria-label="Permalink to “在Ubuntu上安装Tomahawk0.8”">​</a></h3><p>作为一个流媒体音乐的粉丝，我会在接下来的几天里体验一下这个应用软件，然后提供一个关于他的改变的更全面的赏析。与此同时，你也可以尝尝鲜。</p><p>在Ubuntu 14.04 LTS和Ubuntu 14.10上可以通过官方PPA获得Tomahawk。</p><pre><code>sudo add-apt-repository ppa:tomahawk/ppa 

sudo apt-get update &amp;&amp; sudo apt-get install tomahawk
</code></pre><p>在官方项目网站上可以找的独立安装程序和更详细的信息。</p>`,20)),u("ul",null,[u("li",null,[e(o,{href:"http://gettomahawk.com/"},{default:l(()=>[...a[0]||(a[0]=[t("访问 Tomahawk 官网",-1)])]),_:1})])]),a[15]||(a[15]=u("hr",null,null,-1)),u("p",null,[a[2]||(a[2]=t("via: ",-1)),e(o,{href:"http://www.omgubuntu.co.uk/2014/11/tomahawk-media-player-returns-new-look-features"},{default:l(()=>[...a[1]||(a[1]=[t("http://www.omgubuntu.co.uk/2014/11/tomahawk-media-player-returns-new-look-features",-1)])]),_:1})]),u("p",null,[a[6]||(a[6]=t("作者：",-1)),e(o,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:l(()=>[...a[3]||(a[3]=[t("Joey-Elijah Sneddon",-1)])]),_:1}),a[7]||(a[7]=t(" 译者：",-1)),e(o,{href:"https://github.com/H-mudcup"},{default:l(()=>[...a[4]||(a[4]=[t("H-mudcup",-1)])]),_:1}),a[8]||(a[8]=t(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:l(()=>[...a[5]||(a[5]=[t("wxy",-1)])]),_:1})]),u("p",null,[a[11]||(a[11]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[9]||(a[9]=[t("LCTT",-1)])]),_:1}),a[12]||(a[12]=t(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:l(()=>[...a[10]||(a[10]=[t("Linux中国",-1)])]),_:1}),a[13]||(a[13]=t(" 荣誉推出",-1))])])}const C=r(m,[["render",h]]);export{x as __pageData,C as default};
